func (g *TodoGroupBy) Aggregate(fns ...runtime.AggregateFunc) entity.TodoGroupByer {
	g.AppendFns(fns...)
	return g
}

// Scan applies the group-by query and scans the result into the given value.
func (g *TodoGroupBy) Scan(ctx context.Context, v any) error {
	ctx = setContextOp(ctx, g.build.ctx, velox.OpQueryGroupBy)
	if g.build == nil {
		return g.sqlScan(ctx, v)
	}
	if err := g.build.prepareQuery(ctx); err != nil {
		return err
	}
	return runtime.ScanWithInterceptors(ctx, g.build, g.build.inters.Todo, g.sqlScan, v)
}
func (g *TodoGroupBy) sqlScan(ctx context.Context, v any) error {
	return runtime.QueryGroupBy(ctx, g.build, g.fields, g.Fns(), v)
}

// clone returns a concrete clone of the TodoQuery for internal use by First/Only.
func (q *TodoQuery) clone() *TodoQuery {
	if q == nil {
		return nil
	}
	c := &TodoQuery{
		config:     q.config,
		ctx:        q.ctx.Clone(),
		inters:     q.inters,
		modifiers:  runtime.CloneSlice(q.modifiers),
		order:      runtime.CloneSlice(q.order),
		path:       q.path,
		predicates: runtime.CloneSlice(q.predicates),
		withFKs:    q.withFKs,
		withOwner:  q.withOwner.clone(),
	}
	return c
}

// loadOwner eagerly loads the "owner" edge for the given nodes.
func (q *TodoQuery) loadOwner(ctx context.Context, query *UserQuery, nodes []*entity.Todo, init func(*entity.Todo), assign func(*entity.Todo, *entity.User)) error {
	query = query.clone()
	fkSeen := make(map[int]struct{}, len(nodes))
	var fks []any
	for _, n := range nodes {
		fkRaw := n.FKValue("user_todos")
		if fkRaw == nil {
			continue
		}
		fkVal := derefFK(fkRaw).(int)
		if _, ok := fkSeen[fkVal]; !ok {
			fkSeen[fkVal] = struct{}{}
			fks = append(fks, any(fkVal))
		}
		if init != nil {
			init(n)
		}
	}
	if len(fks) == 0 {
		return nil
	}
	query.Where(func(s *sql.Selector) {
		s.Where(sql.In(s.C(user.FieldID), fks...))
	})
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	neighborByID := make(map[int]*entity.User, len(neighbors))
	for _, n := range neighbors {
		neighborByID[n.ID] = n
	}
	for _, n := range nodes {
		fkRaw := n.FKValue("user_todos")
		if fkRaw == nil {
			continue
		}
		fkVal := derefFK(fkRaw).(int)
		if neighbor, ok := neighborByID[fkVal]; ok {
			assign(n, neighbor)
		}
	}
	return nil
}

// Verify TodoQuery implements entity.TodoQuerier at compile time.
var _ entity.TodoQuerier = (*TodoQuery)(nil)
